import math
# Basic key presence
required = ['guest_count', 'type_count', 'bag_size', 'r_list_str']
for key in required:
    if key not in assign:
        # Missing key
        return (False, None)
try:
    g = int(assign['guest_count'])
    k = int(assign['type_count'])
    S_claim = int(assign['bag_size'])
    r_list_raw = str(assign['r_list_str'])
except Exception:
    # Type issues
    return (False, None)
# Parse r_list
try:
    r_list = [int(s.strip()) for s in r_list_raw.split(',') if s.strip() != '']
except Exception:
    return (False, None)
# Validate lengths and positivity
if len(r_list) != k or k < 3 or g < 3:
    return (False, None)
if any(x <= 0 for x in r_list):
    return (False, None)
S = sum(r_list)
if S != S_claim:
    # Inconsistent bag size
    return (False, None)
# Enforce nontrivial difficulty: mixed quotas, not all ones
if not (any(x > 1 for x in r_list) and any(x == 1 for x in r_list)):
    return (False, None)
# Compute probability P = [(S!)^g * prod_i (g*r_i)!] / [(g*S)! * prod_i (r_i!)^g]
# Use integer arithmetic exactly
def fact(n):
    return math.factorial(n)
num = pow(fact(S), g)
den = fact(g * S)
for r in r_list:
    num *= fact(g * r)
    den *= pow(fact(r), g)
# Reduce the fraction
gval = math.gcd(num, den)
num //= gval
den //= gval
if num <= 0 or den <= 0:
    return (False, None)
answer = num + den
